{
  "title": "add_exploration_nudge_flag",
  "request": "Can we add a flag to turn off the exploration nudge? I'd like an `enable_exploration_nudge` bool param in Agent init (default True) and have `_inject_exploration_nudge` early‑exit when it's False.",
  "edits": [
    {
      "path": "browser_use/agent/service.py",
      "search": "        enable_planning: bool = True,",
      "replace": "        enable_planning: bool = True,\n        enable_exploration_nudge: bool = True,"
    },
    {
      "path": "browser_use/agent/service.py",
      "search": "        self._url_shortening_limit = _url_shortening_limit",
      "replace": "        self._url_shortening_limit = _url_shortening_limit\n        self.enable_exploration_nudge = enable_exploration_nudge"
    },
    {
      "path": "browser_use/agent/service.py",
      "search": "    def _inject_exploration_nudge(self) -> None:",
      "replace": "    def _inject_exploration_nudge(self) -> None:\n        if not getattr(self, \"enable_exploration_nudge\", True):\n            return"
    }
  ],
  "test_path": "tests/test_agent_exploration_nudge.py",
  "test": "import inspect\n\nfrom browser_use.agent.service import Agent\n\ndef test_agent_init_has_exploration_nudge_flag():\n    sig = inspect.signature(Agent.__init__)\n    assert 'enable_exploration_nudge' in sig.parameters, \"enable_exploration_nudge param missing\"\n    param = sig.parameters['enable_exploration_nudge']\n    # default should be True\n    assert param.default is True\n"
}
